-- ==========================================================================
-- PART 1: 20260923000001_island_greeting
-- ==========================================================================
begin;
-- The island's own greeting.
--
-- Irie opened every conversation with "Wah Gwaan!" — Jamaican Patois, hardcoded in the client. It
-- is correct on one island and borrowed on the other two, and the whole reason to open in dialect
-- is that it reads as built *here* rather than built for here. A guest in Bridgetown greeted in
-- Jamaican gets the opposite signal.
--
-- It lives beside `in_app_brand` because it is the same kind of thing: the localized in-app voice
-- of a market, set per island, so a new market arrives with its own rather than inheriting one.
alter table islands add column greeting text not null default 'Hello!';

comment on column islands.greeting is
  'How this island says hello, in its own words — Irie''s opening line. Localized per market.';

update islands set greeting = 'Wah Gwaan!'   where code = 'JM';
update islands set greeting = 'Wah goin on!' where code = 'KY';
update islands set greeting = 'Wuh gine on!' where code = 'BB';
update islands set greeting = 'Wah gwan!'    where code = 'AG';
commit;

-- ==========================================================================
-- PART 2: 20261014000001_listing_text_limits
-- ==========================================================================
begin;
-- Bound the listing text columns.
--
-- `title`, `summary`, `description` and `pickup_info` were created as plain `text` with no length
-- constraint, and nothing above them bounded either: no Zod schema, no `maxLength` on the vendor
-- form. The longest title the platform accepted was whatever fit in a request body, on a product
-- whose guest app is a 390pt phone frame.
--
-- The limits match `LISTING_LIMITS` in `packages/types/src/listing.ts` and the inputs in
-- `apps/vendor-web/app/listings/page.tsx`. All three move together or the save button starts
-- failing for reasons a vendor cannot see.
--
-- The longest values in the seeded catalogue are title 35, summary 76, description 297 and pickup
-- 54, so every existing row passes with room to spare. `not valid` is deliberately NOT used: these
-- should be checked on the rows that are already here, and they are.

-- A title also has to say something. `listingTextSchema` rejects a blank or whitespace-only title
-- and nothing here did, so '   ' was storable: `char_length('   ') <= 120` is true, and the column
-- has no not-null or non-empty check. `btrim` rather than a plain length test, so the two layers
-- agree on what empty means — Zod trims before it measures.

alter table experiences
  add constraint experiences_title_length check (char_length(title) <= 120),
  add constraint experiences_title_not_blank check (char_length(btrim(title)) > 0),
  add constraint experiences_summary_length check (char_length(summary) <= 280),
  add constraint experiences_description_length check (char_length(description) <= 2000),
  add constraint experiences_pickup_info_length check (char_length(pickup_info) <= 280);

alter table vendor_organizations
  add constraint vendor_organizations_description_length check (char_length(description) <= 600);
commit;

-- ==========================================================================
-- PART 3: 20261019000001_listings_rls_can_manage
-- ==========================================================================
begin;
-- Enforce vendor_members.can_manage_listings in RLS.
--
-- PRD §4: "vendor staff have no access to payout or account ownership settings unless granted."
-- The column has existed since 20260802000003_vendors.sql and the vendor portal selects it in
-- lib/session.tsx, but no policy ever read it: every `*_vendor_all` policy below authorised writes
-- on `is_vendor_member()` alone, so any vendor_staff row could create, edit and delete its
-- organisation's listings. The flag was collected and discarded.
--
-- Two choices are load-bearing here:
--
-- 1. READ stays member-wide. The old policies were `for all`, so they also governed SELECT.
--    Gating the whole policy on the flag would stop a scan-only staff member from seeing their own
--    organisation's draft listings, which the portal needs. Read and write are therefore split.
--
-- 2. A vendor_owner always manages listings. `can_manage_listings` defaults to false, so requiring
--    the flag outright would lock an owner out of their own inventory the moment a membership row
--    is created without it. Ownership implies the grant; the flag only ever widens staff.
--
-- Scope is listings and their children. `promotions` keeps `is_vendor_member()` because no
-- corresponding permission column exists for it — see OD/open-decisions before widening this.

-- --------------------------------------------------------------------------
-- Helper
-- --------------------------------------------------------------------------
--
-- Named for the question it answers, not for the column, so the column reference inside the body
-- stays unambiguous.

create or replace function is_vendor_listing_manager(org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from vendor_members m
    where m.vendor_org_id = org_id
      and m.user_id = auth.uid()
      and (m.role = 'vendor_owner' or m.can_manage_listings)
  );
$$;

comment on function is_vendor_listing_manager(uuid) is
  'True when the current user may write the org''s listings: owner, or staff granted can_manage_listings.';

-- --------------------------------------------------------------------------
-- experiences
-- --------------------------------------------------------------------------

drop policy experiences_vendor_all on experiences;

create policy experiences_vendor_read on experiences
  for select to authenticated
  using (is_vendor_member(vendor_org_id) or is_admin());

create policy experiences_vendor_insert on experiences
  for insert to authenticated
  with check (is_vendor_listing_manager(vendor_org_id) or is_admin());

create policy experiences_vendor_update on experiences
  for update to authenticated
  using (is_vendor_listing_manager(vendor_org_id) or is_admin())
  with check (is_vendor_listing_manager(vendor_org_id) or is_admin());

create policy experiences_vendor_delete on experiences
  for delete to authenticated
  using (is_vendor_listing_manager(vendor_org_id) or is_admin());

