-- ==========================================================================
-- PART 4: 20261019000002_revoke_availability_rpcs
-- ==========================================================================
begin;
-- Take reserve_availability() and release_availability() off the public API.
--
-- Both are `security definer`, so they write availability_slots with RLS bypassed, and both were
-- executable by PUBLIC — the default for a new function. PUBLIC includes `anon`, so anyone holding
-- the anon key, which ships in the browser bundle by design, could call them without an account.
--
-- Verified before this migration: as `anon` with no JWT, reserve_availability(slot, 12) moved a
-- 12-seat slot from 0 booked to 12 booked with no bookings behind it. Repeated across slots that
-- empties the marketplace, and release_availability() is the mirror — lower booked_count while
-- bookings still exist and the vendor oversells the boat.
--
-- Neither function needs to be reachable from a browser. The only callers are in
-- supabase/functions/_shared/supabaseStore.ts, which runs on the service role, so the grant is
-- narrowed to that role rather than the functions being rewritten to check the caller.
--
-- REVOKE FROM PUBLIC, not from anon and authenticated. A grant held by PUBLIC applies to every
-- role, so revoking the two named roles leaves the privilege in place and changes nothing. The
-- test asserts the denial rather than trusting this comment.

revoke execute on function reserve_availability(uuid, integer) from public;
revoke execute on function release_availability(uuid, integer) from public;

-- Belt and braces: Supabase projects sometimes carry explicit role grants from earlier tooling,
-- and revoking a privilege that was never granted is not an error.
revoke execute on function reserve_availability(uuid, integer) from anon, authenticated;
revoke execute on function release_availability(uuid, integer) from anon, authenticated;

grant execute on function reserve_availability(uuid, integer) to service_role;
grant execute on function release_availability(uuid, integer) to service_role;
commit;

-- ==========================================================================
-- PART 5: 20261020000001_vendor_onboarding
-- ==========================================================================
begin;
-- Vendor onboarding writes a real organisation.
--
-- apps/vendor-web/app/onboarding/page.tsx collected six fields, slept 800ms and routed to
-- /billing. Nothing was stored, so a live deployment would hold zero vendor_organizations rows —
-- and every public RLS policy gates on status = 'approved', so it would also show zero listings.
--
-- ## Why this has to be a function and not two client inserts
--
-- The obvious shape is two PostgREST calls: insert the organisation under vendor_orgs_insert
-- (`with check (auth.uid() is not null)`), then insert the owner membership. The second call
-- CANNOT SUCCEED. The only insert-side policy on vendor_members is vendor_members_owner_manage,
-- whose check is `is_vendor_owner(vendor_org_id) or is_admin()`, and is_vendor_owner() reads
-- vendor_members for an existing 'vendor_owner' row. Before the first member row exists there is
-- no owner, so the policy refuses the very row that would create one.
--
-- So this is not the usual "two writes might half-fail" argument. The client path does not race;
-- it always lands an ownerless organisation, which is then unreachable forever:
-- vendor_orgs_owner_update needs is_vendor_owner() too, and vendor_orgs_member_read needs
-- is_vendor_member(), so the applicant cannot even see the row they just created. One
-- `security definer` function doing both under one transaction is the only shape that works.
--
-- ## The grant
--
-- `security definer` bypasses RLS, so EXECUTE is the only thing standing between a caller and
-- these tables — see 20261019000002, where two such functions sat on the default PUBLIC grant and
-- let anyone holding the browser's anon key rewrite availability. REVOKE FROM PUBLIC first
-- (revoking from anon/authenticated alone is a no-op while PUBLIC holds the grant), then grant to
-- `authenticated` only.
--
-- The owner is read from auth.uid() rather than taken as a parameter. A p_user_id argument on a
-- definer function is an impersonation primitive: any signed-in caller could make someone else the
-- owner of an organisation, or themselves the owner of a hand-picked id.

-- --------------------------------------------------------------------------
-- The two columns the form had nowhere to put
-- --------------------------------------------------------------------------
--
-- vendor_organizations had contact_email and contact_phone but no contact_name, while the form
-- asks for "Primary contact". business_type had no column at all. Both were discarded on submit;
-- adding them is what makes the write lossless.
--
-- Bounded in all three live layers (see the decision record of 2026-10-19): VENDOR_LIMITS and the
-- schemas in packages/types/src/vendor.ts, the checks here, and maxLength on the inputs.
-- `char_length(null)` is null and a CHECK passes on null, which is what lets these sit on
-- nullable columns; btrim for the non-blank tests, because Zod trims before it measures.

alter table vendor_organizations
  add column contact_name  text,
  add column business_type text;

alter table vendor_organizations
  add constraint vendor_organizations_legal_name_length
    check (char_length(legal_name) <= 120),
  add constraint vendor_organizations_legal_name_not_blank
    check (char_length(btrim(legal_name)) > 0),
  add constraint vendor_organizations_trading_name_length
    check (char_length(trading_name) <= 120),
  add constraint vendor_organizations_trading_name_not_blank
    check (char_length(btrim(trading_name)) > 0),
  add constraint vendor_organizations_contact_name_length
    check (char_length(contact_name) <= 120),
  add constraint vendor_organizations_contact_phone_length
    check (char_length(contact_phone) <= 40),
  -- Mirrors VENDOR_BUSINESS_TYPES. A text column with a check rather than an enum: the taxonomy is
  -- marketing copy that will be re-cut, and a check constraint is one ALTER to change where an
  -- enum value can never be removed.
  add constraint vendor_organizations_business_type
    check (business_type is null or business_type in (
      'tour', 'food', 'wellness', 'water', 'culture', 'transport', 'retail', 'other'
    ));

-- --------------------------------------------------------------------------
-- create_vendor_organization
-- --------------------------------------------------------------------------

create or replace function create_vendor_organization(
  p_island_id     uuid,
  p_legal_name    text,
  p_trading_name  text,
  p_contact_name  text,
  p_contact_phone text,
  p_business_type text,
  p_description   text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user  uuid := auth.uid();
  v_email text;
  v_org   uuid;
begin
  if v_user is null then
    raise exception 'Sign in before applying.' using errcode = '42501';
  end if;

  -- An applicant gets one organisation. Without this, a double-submitted form — or a refresh on
  -- /onboarding — leaves two pending applications for one business, and an admin reviewing the
  -- queue has no way to tell which is the real one.
  if exists (select 1 from vendor_members where user_id = v_user) then
    raise exception 'This account already belongs to a vendor organisation.'
      using errcode = '23505';
  end if;

  -- contact_email is not null on the table and is the only address the approval mail can go to, so
  -- it comes from the authenticated identity rather than the form: a self-declared contact address
  -- on a definer function is a way to receive another business's review correspondence. An
  -- anonymous session has no email, which is also why the vendor portal signs in by magic link.
  select email into v_email from auth.users where id = v_user;
  if v_email is null or btrim(v_email) = '' then
    raise exception 'This account has no email address; apply from an email sign-in.'
      using errcode = '42501';
  end if;

  -- The island is a not-null FK, and an application filed under a market that has not launched
  -- would sit in the queue forever. islands_public_read only exposes active islands anyway, so
  -- this is the server-side half of a choice the client could not legitimately make.
  if not exists (select 1 from islands where id = p_island_id and is_active) then
    raise exception 'That island is not open for applications.' using errcode = '23503';
  end if;

  -- 'pending_review', not 'pending' — see the vendor_status enum, whose states are draft,
  -- pending_review, approved, changes_requested, rejected, suspended. The column DEFAULTS to
  -- 'draft', which would leave a completed application looking unsubmitted and absent from any
  -- review queue, so it is set explicitly here.
  insert into vendor_organizations (
    island_id, legal_name, trading_name, contact_email, contact_phone,
    contact_name, business_type, description, status
  )
  values (
    p_island_id, p_legal_name, p_trading_name, v_email, p_contact_phone,
    p_contact_name, p_business_type, p_description, 'pending_review'
  )
  returning id into v_org;

  -- can_manage_listings is false by default and stays false: isListingManager() and the RLS helper
  -- both treat an owner as a manager whatever the flag says, so setting it here would only create a
  -- second source of truth that could disagree. can_view_payouts is the owner's by right.
  insert into vendor_members (vendor_org_id, user_id, role, can_scan_vouchers, can_view_payouts)
  values (v_org, v_user, 'vendor_owner', true, true);

  -- The applicant named a contact; profiles.display_name is where the portal reads a human name
  -- from. Only filled if blank, so this cannot overwrite a name the user chose themselves.
  update profiles
     set display_name = p_contact_name
   where id = v_user
     and p_contact_name is not null
     and coalesce(btrim(display_name), '') = '';

  return v_org;
end;
$$;

revoke execute on function create_vendor_organization(uuid, text, text, text, text, text, text)
  from public;
revoke execute on function create_vendor_organization(uuid, text, text, text, text, text, text)
  from anon;
grant execute on function create_vendor_organization(uuid, text, text, text, text, text, text)
  to authenticated;
commit;

-- ==========================================================================
-- PART 6: 20261020000002_guard_vendor_review_fields
-- ==========================================================================
begin;
-- Only an admin may move a vendor's review state.
--
-- `vendor_orgs_owner_update` grants an owner `for update using (is_vendor_owner(id))`, and RLS has
-- no column-level control, so that policy covered `status` along with the trading name. A vendor
-- owner could therefore approve their own organisation.
--
-- Verified before this migration: as the owner of a `pending_review` organisation, a plain
-- `update vendor_organizations set status = 'approved'` succeeded. Since onboarding makes the
-- applicant a `vendor_owner`, anyone who completed it could make themselves publicly visible
-- without review — and PRD §1 sells the marketplace on verified vendors, with every public policy
-- gating on `status = 'approved'`.
--
-- A trigger rather than a policy, because the privilege is per-column and RLS is per-row. This
-- mirrors `guard_profile_privileges()`, which exists for exactly the same reason: a tourist must
-- not be able to set their own `profiles.role` even though they may update their own profile row.
--
-- Column privileges would not work here either. Admins and vendors are both the `authenticated`
-- database role, so `grant update (…) on vendor_organizations to authenticated` cannot tell them
-- apart. The caller's identity is only visible to a function.

create or replace function guard_vendor_review_fields()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- No end-user context means a service-role caller: an Edge Function, a migration or the seed,
  -- all of which already hold the service key and sit inside the trust boundary. `anon` also has
  -- no uid, but has no UPDATE policy on this table, so RLS refuses it before this runs.
  if auth.uid() is null then
    return new;
  end if;

  if new.status is distinct from old.status
     or new.review_notes is distinct from old.review_notes
     or new.reviewed_by is distinct from old.reviewed_by
     or new.reviewed_at is distinct from old.reviewed_at
  then
    if not is_admin() then
      raise exception 'only a platform administrator may change a vendor''s review state';
    end if;
  end if;

  return new;
end;
$$;

comment on function guard_vendor_review_fields() is
  'Blocks non-admin writes to vendor_organizations.status and its review columns. RLS cannot express a per-column rule.';

create trigger vendor_organizations_review_guard
  before update on vendor_organizations
  for each row execute function guard_vendor_review_fields();

-- `reviewed_by` should name the admin who decided, and the console has no business being trusted
-- to send the right id. Stamp it from the authenticated identity instead.
create or replace function stamp_vendor_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status is distinct from old.status and auth.uid() is not null then
    new.reviewed_by := auth.uid();
    new.reviewed_at := now();
  end if;
  return new;
end;
$$;

-- Postgres fires same-timing triggers in alphabetical order by name, so `…_review_guard` runs
-- before `…_review_stamp`: a refused update raises before this one can stamp anything. The names
-- carry that ordering, so do not rename either without checking the other.
create trigger vendor_organizations_review_stamp
  before update on vendor_organizations
  for each row execute function stamp_vendor_review();
commit;

-- ==========================================================================
-- PART 7: 20261020000003_redeem_voucher_entry_point
-- ==========================================================================
begin;
-- Give the scanner a redemption RPC it can actually call, and stop the old one being callable.
--
-- `apps/vendor-web/lib/redeem.ts` called `redeem_voucher({p_token, p_scanner_name})`. No migration
-- ever defined that signature — the only one was `redeem_voucher(p_token_hash, p_vendor_org_id,
-- p_scanner_user_id, p_device_meta)`. The two-argument contract existed only in the hand-written
-- `packages/supabase/src/database.types.ts`, so `pnpm typecheck` passed and PostgREST returned
-- PGRST202 at runtime: every live scan threw. Demo mode hid it, because `isDemoScanner`
-- short-circuits before the RPC.
--
-- The old function was also executable by PUBLIC and took the scanner's identity and the vendor
-- org as parameters, checking neither against the caller. Verified before this migration: a
-- tourist with no vendor membership redeemed an organisation's voucher (`ok`, voucher burned,
-- `redeemed_by` set to whatever uuid was passed), and a `vendor_staff` with
-- `can_scan_vouchers = false` redeemed one too. `can_scan_for_vendor()` has existed since the
-- first functions migration and was referenced by nothing.
--
-- Shape: the decision logic is untouched and becomes an internal engine; a thin authenticated
-- entry point sits in front of it.

-- --------------------------------------------------------------------------
-- The hash, in one place
-- --------------------------------------------------------------------------
--
-- Must equal `hashVoucherToken()` in packages/types/src/voucher.ts: **base64url** of the sha256,
-- unpadded, of the trimmed token. Two ways to get this wrong, both of which make a valid voucher
-- report `unknown_token` — indistinguishable from a forged QR at the gate:
--
--   1. `encode(…, 'base64')` is standard base64. Its `+`, `/` and `=` are `-`, `_` and nothing in
--      base64url. pgcrypto also wraps long base64 output; a 32-byte digest never reaches the wrap
--      width, but stripping newlines costs nothing and removes the question.
--   2. `btrim(x)` strips SPACES ONLY, while JavaScript `.trim()` also strips newlines, tabs and
--      carriage returns. A scanner that appends a newline would hash to something else entirely.
--      Hence the regexp, which matches `\s` as `.trim()` does.
--
-- It lives in its own function so the entry point and `supabase/tests/voucher_hash.test.sql`
-- exercise the same expression rather than two copies that can drift.

create or replace function voucher_token_hash(p_token text)
returns text
language sql
immutable
set search_path = public
as $$
  select rtrim(
    translate(
      replace(
        encode(
          digest(convert_to(regexp_replace(p_token, '^\s+|\s+$', '', 'g'), 'UTF8'), 'sha256'),
          'base64'
        ),
        E'\n', ''
      ),
      '+/', '-_'
    ),
    '='
  );
$$;

comment on function voucher_token_hash(text) is
  'base64url sha256 of the trimmed voucher token. Mirrors hashVoucherToken() in @cvip/types.';

-- --------------------------------------------------------------------------
-- The engine
-- --------------------------------------------------------------------------
--
-- Renamed rather than rewritten, so the row lock, the branch ordering and every outcome stay
-- byte-identical — `atomicity.test.sql` covers all ten branches through this function and keeps
-- doing so. It still trusts its arguments, which is now acceptable because only the service role
-- can call it: Edge Functions and the test suite.

alter function redeem_voucher(text, uuid, uuid, jsonb) rename to redeem_voucher_by_hash;

revoke execute on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) from public;
revoke execute on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) from anon, authenticated;
grant execute on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) to service_role;

comment on function redeem_voucher_by_hash(text, uuid, uuid, jsonb) is
  'Redemption decision engine. Trusts its arguments, so it is service-role only; authenticated callers use redeem_voucher(text, uuid).';

-- --------------------------------------------------------------------------
-- The entry point the scanner calls
-- --------------------------------------------------------------------------
--
-- Takes the raw token from the QR code and the organisation the scanner believes it is scanning
-- for. It derives the scanner from `auth.uid()` and refuses unless that user holds
-- `can_scan_vouchers` for the named organisation, so neither the identity nor the permission is
-- the client's to assert.
--
-- Hashing is `voucher_token_hash()` above, which is pinned against the TypeScript codec by
-- `supabase/tests/voucher_hash.test.sql` and `packages/types/src/voucher.test.ts`.
--
-- The HMAC signature is NOT verified here: the signing secret is deliberately server-side only and
-- has no business in the database. A tampered or fabricated QR therefore fails by hash miss and
-- reports `unknown_token`, which is the same answer a scanner needs, and the attempt is still
-- recorded in `voucher_redemptions`.

create or replace function redeem_voucher(
  p_token         text,
  p_vendor_org_id uuid
)
returns table (
  result               redemption_result,
  voucher_id           uuid,
  redeemed_at          timestamptz,
  original_redeemed_at timestamptz,
  original_scanner     text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scanner uuid := auth.uid();
  v_hash    text;
  r         record;
begin
  if v_scanner is null then
    raise exception 'redeem_voucher requires a signed-in scanner';
  end if;

  if not can_scan_for_vendor(p_vendor_org_id) then
    -- Not a redemption outcome. A scanner without the permission is a configuration problem for
    -- the vendor to fix, not something to render as a decision about the guest's voucher.
    raise exception 'you do not have permission to scan vouchers for this organisation';
  end if;

  v_hash := voucher_token_hash(p_token);

  select * into r
    from redeem_voucher_by_hash(v_hash, p_vendor_org_id, v_scanner, '{}'::jsonb);

  return query
    select r.result,
           r.voucher_id,
           r.redeemed_at,
           r.original_redeemed_at,
           (select p.display_name from profiles p where p.id = r.original_scanner_id);
end;
$$;

revoke execute on function redeem_voucher(text, uuid) from public;
grant execute on function redeem_voucher(text, uuid) to authenticated;

comment on function redeem_voucher(text, uuid) is
  'Scanner entry point. Hashes the token, derives the scanner from auth.uid() and requires can_scan_vouchers for the named organisation.';
commit;

-- ==========================================================================
-- PART 8: 20261021000001_my_bookings
-- ==========================================================================
begin;
-- my_bookings(): the signed-in tourist's paid bookings, for recovery on a new device.
--
-- A tourist who adds an email and signs in on another phone has an empty local store. Their
-- bookings are on the server, and the owner can already read the `bookings` rows themselves
-- (`bookings_self_read`). What they cannot reliably read is what the booking points at:
--
--   - `availability_slots_public_read` requires `status = 'open'`, so a departure the vendor
--     cancelled after the guest paid loses its `starts_at`.
--   - `experiences_public_read` requires an approved listing under an approved vendor, so a
--     vendor suspended after the guest paid loses the listing title AND (through the same join
--     in the slot policy) the departure time.
--
-- Those are precisely the bookings a guest most needs to see — to know what was cancelled and
-- what they are owed. Widening the public policies to "or you hold a booking against it" would put
-- a bookings subquery on every catalogue read, so this is a narrow `security definer` read instead.
--
-- Because it is security definer, RLS does not protect what it returns. The `user_id = auth.uid()`
-- predicate below IS the access control: with no uid it compares against null and matches nothing,
-- so an anonymous or service-role call returns zero rows rather than every row.
-- supabase/tests/my_bookings.test.sql asserts each of these.
--
-- `pending_payment` and `expired` are excluded: an unpaid checkout is not a booking the guest has,
-- and showing it would put a ticket-less card in Trips.
--
-- Times are returned as `timestamptz`. The tourist app treats slot times as UTC wall-clock (see
-- supabase/functions/resolve-slot/index.ts), and converts back on its side.

create or replace function my_bookings()
returns table (
  id                uuid,
  reference         text,
  status            booking_status,
  seats             integer,
  currency          currency_code,
  subtotal_minor    bigint,
  tax_minor         bigint,
  service_fee_minor bigint,
  total_minor       bigint,
  created_at        timestamptz,
  ticket_token      text,
  experience_title  text,
  island_code       text,
  starts_at         timestamptz,
  guests            jsonb
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.id,
    b.reference,
    b.status,
    b.seats,
    b.currency,
    b.subtotal_minor,
    b.tax_minor,
    b.service_fee_minor,
    b.total_minor,
    b.created_at,
    b.ticket_token,
    e.title,
    i.code,
    s.starts_at,
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'kind',              o.kind,
                   'label',             o.label,
                   'quantity',          g.quantity,
                   'unit_amount_minor', g.unit_amount_minor
                 )
                 order by o.sort_order, g.created_at, g.id
               )
          from booking_guests g
          join experience_options o on o.id = g.experience_option_id
         where g.booking_id = b.id
      ),
      '[]'::jsonb
    )
  from bookings b
  join experiences e        on e.id = b.experience_id
  join islands i            on i.id = e.island_id
  join availability_slots s on s.id = b.availability_slot_id
  where b.user_id = auth.uid()
    and b.status in ('confirmed', 'completed', 'cancelled', 'refunded')
  order by s.starts_at desc, b.created_at desc;
$$;

-- REVOKE FROM PUBLIC, not only from anon: a PUBLIC grant applies to every role, so revoking the
-- named role alone changes nothing. The explicit anon revoke covers Supabase projects whose default
-- privileges grant EXECUTE on new functions to anon directly.
revoke execute on function my_bookings() from public;
revoke execute on function my_bookings() from anon;

grant execute on function my_bookings() to authenticated;
-- Edge Functions run as service_role. With no uid they get zero rows, which the test asserts.
grant execute on function my_bookings() to service_role;

comment on function my_bookings() is
  'The caller''s confirmed/completed/cancelled/refunded bookings with slot time, listing title, island code and guests. Security definer so slot/listing RLS cannot hide them; filters on auth.uid().';
commit;

-- ==========================================================================
-- PART 9: 20261021000002_revoke_anon_redeem_voucher
-- ==========================================================================
begin;
-- redeem_voucher(text, uuid) was revoked from PUBLIC only.
--
-- Supabase's default privileges grant EXECUTE on new functions to anon directly, and a PUBLIC
-- revoke does not remove a grant made to a named role. The function still refuses a caller with
-- no uid, so this is hardening and not a live hole, but an unauthenticated caller should not be
-- able to reach it at all. The local harness cannot show the difference (it has no such default
-- grant), so this is verified against a real project, not by supabase/tests.

revoke execute on function redeem_voucher(text, uuid) from anon;
commit;

-- ==========================================================================
-- PART 10: 20261021000003_my_bookings_ticket_token_by_status
-- ==========================================================================
begin;
-- my_bookings(): no scannable ticket for a cancelled or refunded booking.
--
-- 20261021000001 returned `b.ticket_token` for every row it returned, including `cancelled` and
-- `refunded`. A booking row can keep the token it was issued after it is cancelled, so a guest
-- (or anyone holding their phone) could recover a QR for a booking that is no longer valid and
-- present it at the gate. The token is now returned only while the booking is `confirmed` or
-- `completed`; otherwise it is null. Everything else about the function is unchanged: same
-- signature, same rows, same ordering, same grants.
--
-- Hardening: search_path is now `public, pg_temp` (pg_temp last, so a temporary object can never
-- shadow a `public` one inside this security definer function).
--
-- `create or replace` keeps the existing grants; they are restated below anyway so this file
-- alone states the privilege model. supabase/tests/my_bookings.test.sql asserts both the token
-- rule (with confirmed/completed positive controls) and the grants.

create or replace function my_bookings()
returns table (
  id                uuid,
  reference         text,
  status            booking_status,
  seats             integer,
  currency          currency_code,
  subtotal_minor    bigint,
  tax_minor         bigint,
  service_fee_minor bigint,
  total_minor       bigint,
  created_at        timestamptz,
  ticket_token      text,
  experience_title  text,
  island_code       text,
  starts_at         timestamptz,
  guests            jsonb
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select
    b.id,
    b.reference,
    b.status,
    b.seats,
    b.currency,
    b.subtotal_minor,
    b.tax_minor,
    b.service_fee_minor,
    b.total_minor,
    b.created_at,
    case when b.status in ('confirmed', 'completed') then b.ticket_token else null end,
    e.title,
    i.code,
    s.starts_at,
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'kind',              o.kind,
                   'label',             o.label,
                   'quantity',          g.quantity,
                   'unit_amount_minor', g.unit_amount_minor
                 )
                 order by o.sort_order, g.created_at, g.id
               )
          from booking_guests g
          join experience_options o on o.id = g.experience_option_id
         where g.booking_id = b.id
      ),
      '[]'::jsonb
    )
  from bookings b
  join experiences e        on e.id = b.experience_id
  join islands i            on i.id = e.island_id
  join availability_slots s on s.id = b.availability_slot_id
  where b.user_id = auth.uid()
    and b.status in ('confirmed', 'completed', 'cancelled', 'refunded')
  order by s.starts_at desc, b.created_at desc;
$$;

revoke execute on function my_bookings() from public;
revoke execute on function my_bookings() from anon;

grant execute on function my_bookings() to authenticated;
grant execute on function my_bookings() to service_role;

comment on function my_bookings() is
  'The caller''s confirmed/completed/cancelled/refunded bookings with slot time, listing title, island code and guests. Ticket token only for confirmed/completed, null otherwise. Security definer so slot/listing RLS cannot hide them; filters on auth.uid().';
commit;
